UPDATE lessons SET title='Year 4, Week 7, Lesson 2: Multi-step problems', data=json_patch(data,'{"child_mission":"Multi-step problems need a plan for each step, a record of intermediate answers and a final check against the question.","coming_soon":null,"duration_minutes":55,"evidence_instructions":"Save the independent response, specific revisions and both short-answer explanations; record oral evidence for speaking tasks.","explicit_teaching":null,"extension":"Apply the same method to a larger number or a new context, then compare two solution paths for accuracy.","follow_up_challenges":null,"guided_practice":"PRACTISE BEFORE READING THE FEEDBACK\nLibrary: 1,850 books; 420 new; then 275 loaned. How many now? Show both steps.\n\nFEEDBACK\n1,850 + 420 = 2,270; 2,270 − 275 = 1,995 books.\n\nWATCH FOR\nStopping after the first calculation leaves the question unfinished.","hoard_words":null,"independent_task":"INDEPENDENT EVIDENCE\nSolve ten multi-step problems. Number the steps, box the final answer and write one check for five items.\n\nWrite a short reflection naming one step you corrected and why.","interactive_activities":null,"learning_area":"Mathematics","learning_intention":"Multi-step problems need a plan for each step, a record of intermediate answers and a final check against the question.","lesson_number":2,"lesson_role":"Strategies","materials":["Paper or typed answer space","Pencil","Optional: place-value chart or number line"],"offline_alternative":"Use paper and pencil to complete the original task, then retain a photograph or short parent observation as evidence.","outcome_codes":["MA2-AR-01"],"parent_notes":"Parent: Marking guidance for the independent task: Solve ten multi-step problems. Number the steps, box the final answer and write one check for five items. Accept equivalent original responses that show the same skill.\n\nParent: Written model 1: Original response on new material: 1,850 + 420 = 2,270; 2,270 − 275 = 1,995 books. Reasoning: I used multi-step by attending to plan rather than copying the worked model.\n\nParent: Written model 2: Common error: Stopping after the first calculation leaves the question unfinished. Correction: 1,850 + 420 = 2,270; 2,270 − 275 = 1,995 books. Why: the correction restores accurate use of multi-step.\n\nParent: Likely misconception: Stopping after the first calculation leaves the question unfinished. Keep sample answers out of the child role.\n\nParent: Short-answer focus 1: Solve one fresh problem that uses multi-step with different numbers from the worked model. Show working and name the places or values that matter.\n\nParent: Short-answer focus 2: Describe one likely mistake with multi-step, show corrected working, and say why the correction works.\n\nParent: Marking notes: Require new numbers, visible working and named places/values. / Require a real misconception, corrected working and a method reason..","pass":1,"pass_mark":0.9,"planner_fields":null,"planner_intro":null,"planner_title":null,"printable_resource":null,"quiz":[{"correct_index":0,"explanation":"1,850 + 420 = 2,270; 2,270 − 275 = 1,995 books. This matches the lesson skill for multi-step.","options":["1,850 + 420 = 2,270; 2,270 − 275 = 1,995 books.","Stopping after the first calculation leaves the question unfinished.","Ignore place value and read digits from left to right as ones only.","Copy the model numbers and call that independent work."],"question":"Library: 1,850 books; 420 new; then 275 loaned. How many now? Show both steps. Which response is most accurate?","type":"multiple_choice"},{"correct_index":0,"explanation":"Stopping after the first calculation leaves the question unfinished. That misconception weakens accuracy; the other choices align with the lesson idea.","options":["Stopping after the first calculation leaves the question unfinished.","Multi-step problems need a plan for each step, a record of intermediate answers and a final check against the question.","1,850 + 420 = 2,270; 2,270 − 275 = 1,995 books.","Careful use of plan with clear evidence."],"question":"Which statement is a common mistake when practising multi-step?","type":"multiple_choice"},{"correct_index":2,"explanation":"Understanding is shown by new evidence and named plan, not by copying the model.","options":["Choose randomly because any option could be right.","Treat a missing zero as if it does not change the value.","Apply the idea with new evidence and name the plan used.","Repeat the worked example wording with no new evidence."],"question":"A learner is practising multi-step. Which approach best shows understanding?","type":"multiple_choice"},{"correct_index":2,"explanation":"Mathematics answers need labelled working tied to place value or quantity.","options":["Change digits to look neater without checking place value.","Stopping after the first calculation leaves the question unfinished.","Show the places, values or steps and say why each step is valid.","Write only a final number with no working."],"question":"Which working note best supports a mathematics answer about multi-step?","type":"multiple_choice"},{"correct_index":3,"explanation":"The correct statement applies the method; the others break it.","options":["Stopping after the first calculation leaves the question unfinished.","Ignore place value and read digits from left to right as ones only.","Copy the model numbers and call that independent work.","1,850 + 420 = 2,270; 2,270 − 275 = 1,995 books."],"question":"Using this lesson idea — Multi-step problems need a plan for each step, a record of intermediate answers and a final check against… — which statement is true?","type":"multiple_choice"},{"correct_index":1,"explanation":"Disagreement is resolved by checking places, operations and the question focus.","options":["Average the two answers without checking either.","Recheck places, operations and whether the question asked for the quantity you computed.","Pick the longer-looking working automatically.","Delete units so the answers appear to match."],"question":"Which error should you repair first if two methods disagree?","type":"multiple_choice"},{"correct_index":3,"explanation":"Transfer requires new numbers with the same method.","options":["Retype the worked model numbers as the answer.","Change only handwriting and keep the same numbers.","Copy the model numbers and call that independent work.","Solve a fresh problem with different numbers and explain the method."],"question":"Which practice choice shows transfer of multi-step?","type":"multiple_choice"},{"correct_index":3,"explanation":"Useful feedback names the failed step and shows corrected working.","options":["Praise neat handwriting even when the places are wrong.","Tell the learner to skip working and only keep the final digits.","Just add more digits until it looks longer.","Name the exact place or step that failed, then show corrected working for multi-step."],"question":"Which feedback comment is most useful after a mistake?","type":"multiple_choice"},{"explanation":"Independent evidence on new material demonstrates the skill; copying the model does not.","marking_guide":"Require new numbers, visible working and named places/values.","question":"Solve one fresh problem that uses multi-step with different numbers from the worked model. Show working and name the places or values that matter.","sample_answer":"Original response on new material: 1,850 + 420 = 2,270; 2,270 − 275 = 1,995 books. Reasoning: I used multi-step by attending to plan rather than copying the worked model.","type":"short_answer"},{"explanation":"A useful correction changes the inaccurate idea or method and explains why.","marking_guide":"Require a real misconception, corrected working and a method reason.","question":"Describe one likely mistake with multi-step, show corrected working, and say why the correction works.","sample_answer":"Common error: Stopping after the first calculation leaves the question unfinished. Correction: 1,850 + 420 = 2,270; 2,270 − 275 = 1,995 books. Why: the correction restores accurate use of multi-step.","type":"short_answer"}],"resources":null,"response_prompt":"Include your independent working and reflection, with reasons where requested.","review_status":"unreviewed","seed_key":"s2-mat-y4-w07-l2","sort_activity":null,"source_note":"Proposed Stage 2 NESA mathematics alignment using verified outcome code wording where recorded in lesson-pipeline/sources; content-point mapping remains pending.","spelling":null,"spelling_focus":null,"stage":"S2","stage_hints":{"accept":["Today you will practise multi-step.","Read the mission before you start calculating.","Keep the place or unit you are working with in view."],"guided":["Attempt the guided prompt without looking ahead.","Afterwards, compare your working with the feedback.","Adjust anything that does not match the method."],"learn":["Study how the first demonstration is built.","Point to the place or distance that carries the method.","Then write the reason without copying every sentence."],"quiz":["Read every option before you choose.","Eliminate answers that ignore place value or working.","Prefer accurate method over a guess that merely looks neat."],"submit":["Confirm that your working and reason are both present.","Proofread digits, places and operation signs.","Make sure the final evidence matches the lesson purpose."],"teach0":["Read the stage title and find the worked model.","Name one exact place, value or distance before you decide.","Try the small prompt before opening the comparison."],"teach1":["Return to the model and list the key numbers.","Say what each number represents in the method.","A final answer alone is weaker than labelled working."],"teach2":["Compare a weak attempt with stronger working.","Change the value or method, not only how neat it looks.","Name the mistake you are repairing."],"teach3":["Choose fresh numbers that still use the same skill.","Write one reason in your own words.","Do not retype the worked model as your answer."],"write":["Follow every part of the independent instructions.","Include original working and a short reason.","Save work that shows the skill on new numbers."]},"subject":"Number and Algebra","success_criteria":["I can use multi-step with a specific example from this lesson.","I can identify plan and explain why it matters.","I can practise check independently on a new prompt.","I can notice operation needs and correct a likely mistake."],"suspense_builder":null,"teach_steps":[{"check":{"correct_index":1,"explanation":"Multi-step problems need a plan for each step, a record of intermediate answers and a final check against the question. Supported working follows the actual numbers and purpose of the task.","options":["A guess with no working.","Multi-step problems need a plan for each step, a record of intermediate answers and a final check against the question.","A calculation unrelated to the numbers given.","An answer copied without understanding."],"question":"Which choice best shows accurate use of this idea about multi-step?","type":"multiple_choice"},"example":"WORKED MODEL\nShop: pack of 24 + pack of 36 stickers; give 15 away. Steps: 24 + 36 = 60; 60 − 15 = 45 left. Check: 45 + 15 = 60.\n\nTRY FIRST\nLibrary: 1,850 books; 420 new; then 275 loaned. How many now? Show both steps.\n\nFEEDBACK\n1,850 + 420 = 2,270; 2,270 − 275 = 1,995 books.","explain":"Multi-step problems need a plan for each step, a record of intermediate answers and a final check against the question.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Stopping after the first calculation leaves the question unfinished. Correct the value or method, not just the appearance of the digits.","title":"Understand and model","visual":[{"alt":"Multi-step plan with intermediate total.","caption":"Box the final answer.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Step 1</text><text x=\"28\" y=\"78\">24+36=60</text><text x=\"358\" y=\"42\">Step 2</text><text x=\"358\" y=\"78\">60−15=45</text></g></svg>"}],"visual_before":[{"episode":{"scenes":[{"bg":"room","lines":[{"text":"I can see the example, but I am not sure which number or place matters most.","who":"pip"},{"text":"Name the places, values or distances that carry the method before you decide.","who":"juno"},{"text":"I will try the prompt myself, then compare with the feedback.","who":"pip"},{"pause_after":true,"text":"Pause here. Use this model: Shop: pack of 24 + pack of 36 stickers; give 15 away. Steps: 24 + 36 = 60; 60 − 15 = 45 left. Check: 45 + 15 = 60. Then write your own working.","who":"juno"}]}],"title":"Talk through the first model","transcript":"Pip: I can see the example, but I am not sure which number or place matters most.\nJuno: Name the places, values or distances that carry the method before you decide.\nPip: I will try the prompt myself, then compare with the feedback.\nJuno: Pause here. Use this model: Shop: pack of 24 + pack of 36 stickers; give 15 away. Steps: 24 + 36 = 60; 60 − 15 = 45 left. Check: 45 + 15 = 60. Then write your own working."}}]},{"check":{"correct_index":3,"explanation":"Make the method visible: name the values, places or steps you used and say why that step is valid. Supported working follows the actual numbers and purpose of the task.","options":["A calculation unrelated to the numbers given.","An answer copied without understanding.","A guess with no working.","Make the method visible: name the values, places or steps you used and say why that step is valid."],"question":"Which choice best shows accurate use of this idea about multi-step?","type":"multiple_choice"},"example":"WORKED MODEL\nShop: pack of 24 + pack of 36 stickers; give 15 away. Steps: 24 + 36 = 60; 60 − 15 = 45 left. Check: 45 + 15 = 60. Look at each number, place or distance that carries the method.\n\nTRY FIRST\nWrite the key numbers from the model and say what each one represents in the method.\n\nFEEDBACK\nThe most useful working names the quantities and the reason for each step, not only the final answer.","explain":"Make the method visible: name the values, places or steps you used and say why that step is valid.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Writing only the final answer without working does not show the method. Correct the value or method, not just the appearance of the digits.","title":"Show the working","visual":[{"alt":"Inverse check contrasted with unfinished work.","caption":"Number every step.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Check</text><text x=\"28\" y=\"78\">45+15=60</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">stop after step 1</text></g></svg>"}]},{"check":{"correct_index":3,"explanation":"Use an intentionally incorrect attempt as a comparison. Name its specific mathematical error, then show the corrected working. Supported working follows the actual numbers and purpose of the task.","options":["A calculation unrelated to the numbers given.","An answer copied without understanding.","A guess with no working.","Use an intentionally incorrect attempt as a comparison. Name its specific mathematical error, then show the corrected working."],"question":"Which choice best shows accurate use of this idea about multi-step?","type":"multiple_choice"},"example":"WORKED MODEL\nStopping after the first calculation leaves the question unfinished. Here is a more productive model: Shop: pack of 24 + pack of 36 stickers; give 15 away. Steps: 24 + 36 = 60; 60 − 15 = 45 left. Check: 45 + 15 = 60.\n\nTRY FIRST\nDescribe why the warned-against approach gives the wrong value or meaning, then write corrected working.\n\nFEEDBACK\n1,850 + 420 = 2,270; 2,270 − 275 = 1,995 books.","explain":"Use an intentionally incorrect attempt as a comparison. Name its specific mathematical error, then show the corrected working.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Changing the answer without repairing the method does not fix the error. Stopping after the first calculation leaves the question unfinished. Correct the value or method, not just the appearance of the digits.","title":"Test a misconception"},{"check":{"correct_index":3,"explanation":"Use the method on new numbers or a new context, not a copy of the worked example. Review accuracy and units or places. Supported working follows the actual numbers and purpose of the task.","options":["A calculation unrelated to the numbers given.","An answer copied without understanding.","A guess with no working.","Use the method on new numbers or a new context, not a copy of the worked example. Review accuracy and units or places."],"question":"Which choice best shows accurate use of this idea about multi-step?","type":"multiple_choice"},"example":"WORKED MODEL\nMulti-step problems need a plan for each step, a record of intermediate answers and a final check against the question. Now choose different numbers to show you can transfer the method.\n\nTRY FIRST\nSolve one fresh problem that uses the same skill and write a short reason for your answer.\n\nFEEDBACK\nThe new problem should use the same method as the model, but contain different numbers.","explain":"Use the method on new numbers or a new context, not a copy of the worked example. Review accuracy and units or places.\n\nWHY IT MATTERS\nThis helps the learner choose methods based on place value, quantity and accurate working, rather than guessing digits by shape alone. Keep every step justified.\n\nHOW TO WORK\nRead the worked example and name the places, values or distances that carry the method. Before looking at the correction, make your own attempt using the exact question provided. Compare your working with the feedback: did you use the same skill and show your reasoning? If a digit or place is uncertain, identify what would have to be regrouped or counted again. One deliberate, justified revision is more useful than writing a longer answer.","icon":"📖","notice":"Repeating the worked example cannot show transfer to new numbers. Correct the value or method, not just the appearance of the digits.","title":"Transfer to a new problem"}],"title":"Year 4, Week 7, Lesson 2: Multi-step problems","unit_number":2,"unit_title":"Addition and subtraction strategies","week":7,"week_in_unit":3,"word_challenges":null,"worked_example":"WORK THROUGH THIS\nShop: pack of 24 + pack of 36 stickers; give 15 away. Steps: 24 + 36 = 60; 60 − 15 = 45 left. Check: 45 + 15 = 60.\n\nWrite what makes this example accurate, naming the places, values or distances used.","worked_visuals":[{"alt":"Multi-step plan with intermediate total.","caption":"Box the final answer.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Step 1</text><text x=\"28\" y=\"78\">24+36=60</text><text x=\"358\" y=\"42\">Step 2</text><text x=\"358\" y=\"78\">60−15=45</text></g></svg>"},{"alt":"Inverse check contrasted with unfinished work.","caption":"Number every step.","svg":"<svg xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 660 150\"><rect x=\"10\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#fff4ea\" stroke=\"#b87445\"/><rect x=\"340\" y=\"12\" width=\"310\" height=\"126\" rx=\"14\" fill=\"#e8f5ed\" stroke=\"#297a61\"/><g font-size=\"16\" fill=\"#263948\"><text x=\"28\" y=\"42\">Check</text><text x=\"28\" y=\"78\">45+15=60</text><text x=\"358\" y=\"42\">Risk</text><text x=\"358\" y=\"78\">stop after step 1</text></g></svg>"}],"year_level":"Year 4"}') WHERE seed_key='s2-mat-y4-w07-l2' AND family_id IS NULL;
